```kotlin
// PaymentCompletedConsumer.kt
@Component
class PaymentCompletedConsumer(
    private val paymentCompletedHandler: PaymentCompletedHandler,
) {
    private val logger = LoggerFactory.getLogger(javaClass)

    @KafkaListener(topics = ["payment-completed"], groupId = "\${kafka.consumer.group-id}")
    suspend fun consume(
        @Payload event: PaymentCompletedEvent,
        @Header(KafkaHeaders.RECEIVED_KEY) key: String,
        @Header("correlation-id", required = false) correlationId: String?,
    ) {
        val cid = correlationId ?: UUID.randomUUID().toString()
        MDC.put("correlationId", cid)
        try {
            logger.info("Received payment-completed event paymentId={}", event.paymentId)
            paymentCompletedHandler.handle(event)
        } finally {
            MDC.clear()
        }
    }
}
```

